import sys

data = sys.stdin.read().split()
n0 = int(data[0])
def isp(v):
    if v < 2:
        return False
    d = 2
    while d * d <= v:
        if v % d == 0:
            return False
        d += 1
    return True
c = 0
a = 2
while 2 * a <= n0:
    if isp(a) and isp(n0 - a):
        c += 1
    a += 1
print(c)

